cat tsconfig.json; cat > /tmp/ren.js <<'EOF'
const fs=require('fs'),path=require('path');
const TAGS=new Set(['app-pill','app-fancy-pill','app-status-pill']);
function walk(d,o=[]){for(const f of fs.readdirSync(d)){const p=path.join(d,f);fs.statSync(p).isDirectory()?walk(p,o):o.push(p);}return o;}
function fix(s){
  let out='',i=0,n=0;
  while(i<s.length){
    if(s.startsWith('<!--',i)){const e=s.indexOf('-->',i);const j=e<0?s.length:e+3;out+=s.slice(i,j);i=j;continue;}
    const m=/^<([a-zA-Z][\w-]*)/.exec(s.slice(i,i+60));
    if(!m){out+=s[i++];continue;}
    // scan tag
    let j=i+m[0].length,q=null;
    while(j<s.length){const c=s[j];if(q){if(c===q)q=null;}else if(c==='"'||c==="'")q=c;else if(c==='>')break;j++;}
    let tag=s.slice(i,j+1);
    if(TAGS.has(m[1])){
      // replace attr names outside quotes
      let r='',k=0;q=null;
      while(k<tag.length){const c=tag[k];
        if(q){if(c===q)q=null;r+=c;k++;continue;}
        if(c==='"'||c==="'"){q=c;r+=c;k++;continue;}
        if(tag.startsWith('disableTooltip',k)&&/[\s\[]/.test(tag[k-1])&&/[\s\]=\/>]/.test(tag[k+14])){r+='hideHint';k+=14;n++;continue;}
        r+=c;k++;}
      tag=r;
    }
    out+=tag;i=j+1;
  }
  return [out,n];
}
let tot=0;
for(const f of walk('src/app')){
  if(!/\.(html|ts)$/.test(f))continue;
  const s=fs.readFileSync(f,'utf8');const [o,n]=fix(s);
  if(n){fs.writeFileSync(f,o);tot+=n;}
}
console.log(tot);
EOF
