cat > /tmp/fix.js <<'EOF'
const fs=require('fs'),cp=require('child_process');
for(let round=0;round<5;round++){
let out='';try{out=cp.execSync('npx ngc -p tsconfig.json 2>&1',{encoding:'utf8'});}catch(e){out=e.stdout||'';}
out=out.replace(/\x1b\[[0-9;]*m/g,'');
const re=/^(\S+?):(\d+):(\d+) - error TS2339: Property 'disableTooltip' does not exist on type '(\w+)'/gm;
let m,byFile={},other=out.split('\n').filter(l=>/error/.test(l)&&!/TS2339: Property 'disableTooltip'/.test(l));
while(m=re.exec(out)){(byFile[m[1]]??=[]).push([+m[2],+m[3],m[4]]);}
console.log('round',round,Object.values(byFile).flat().length,'other',other);
if(!Object.keys(byFile).length){break;}
for(const f in byFile){const lines=fs.readFileSync(f,'utf8').split('\n');
 for(const [l,c,t] of byFile[f].sort((a,b)=>b[0]-a[0]||b[1]-a[1])){const s=lines[l-1];
  if(s.substr(c-1,14)!=='disableTooltip'){console.log('MISMATCH',f,l,c,t);continue;}
  lines[l-1]=s.slice(0,c-1)+'hideHint'+s.slice(c+13);console.log(f,l,t);}
 fs.writeFileSync(f,lines.join('\n'));}
}
EOF
